impl Solution {
    pub fn longest_mountain(arr: Vec<i32>) -> i32 {
        let n = arr.len();
        if n < 3 {
            return 0;
        }

        let mut max_len = 0;
        let mut i = 1;

        while i < n - 1 {
            let mut up = 0;
            let mut down = 0;

            // Check if current element is the start of an up sequence
            if arr[i] > arr[i - 1] {
                up = 1;
                while i + up < n && arr[i + up] > arr[i + up - 1] {
                    up += 1;
                }

                // Check if there's a down sequence after the up sequence
                if i + up < n && arr[i + up] < arr[i + up - 1] {
                    down = 1;
                    while i + up + down < n && arr[i + up + down] < arr[i + up + down - 1] {
                        down += 1;
                    }

                    // Update max_len if a valid mountain is found
                    if up > 0 && down > 0 {
                        max_len = max_len.max(up + down + 1);
                    }

                    i += up + down;
                } else {
                    i += up;
                }
            } else {
                i += 1;
            }
        }

        max_len as i32
    }
}

